SET NOCOUNT ON; SET XACT_ABORT ON;
IF DB_NAME() NOT LIKE N'OptionCIsolated[_]%' THROW 52000,N'CANDIDATE_DISPOSABLE_TARGET_REQUIRED',1;
IF EXISTS(SELECT 1 FROM dbo.SchemaVersions WHERE VersionNumber=N'1.8.0-013') THROW 52001,N'RESERVED_013_DETECTED_STOP',1;
IF (SELECT TOP(1) VersionNumber FROM dbo.SchemaVersions ORDER BY AppliedAt DESC,VersionNumber DESC)<>N'1.8.0-011' THROW 52002,N'EXPECTED_1.8.0-011_STOP',1;
IF EXISTS(SELECT 1 FROM dbo.SchemaVersions WHERE VersionNumber=N'1.8.0-012') THROW 52003,N'1.8.0-012_RERUN_STOP',1;
BEGIN TRY BEGIN TRANSACTION; ALTER TABLE dbo.ChangeRequests ADD ReviewedAt datetime2(3) NULL,ReviewReason nvarchar(1000) NULL,AppliedAt datetime2(3) NULL,CONSTRAINT CK_Candidate_ReviewState CHECK((Status=N'Pending' AND ReviewerUserId IS NULL AND AppliedAt IS NULL) OR (Status IN(N'Approved',N'Rejected',N'Applied') AND ReviewerUserId IS NOT NULL AND ReviewerUserId<>RequestedByUserId)); ALTER TABLE dbo.ChangeRequestEvents ADD CONSTRAINT CK_Candidate_EventType CHECK(EventType IN(N'Submitted',N'LeaderApproved',N'LeaderRejected',N'Approved',N'Rejected',N'Applied')); INSERT dbo.SchemaVersions(VersionNumber,Description,AppliedAt,AppliedBy) VALUES(N'1.8.0-012',N'R3 candidate 1800_012',SYSUTCDATETIME(),N'candidate-rehearsal'); COMMIT; SELECT N'UP_OK' Result,N'1.8.0-012' Marker; END TRY BEGIN CATCH IF @@TRANCOUNT>0 ROLLBACK; THROW; END CATCH;
